// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Step 12: Read offers with no pick": "in1_Step12Readofferswithnopi"};
const LISTS = ["Step 12: Read offers with no pick"];
const EXECUTED = ["Step 12: Every hour"];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Step 12: Read offers with no pick";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
// Step 12: Read offers with no pick: each offer older than pick_hours with no later row for its job (n8n's SQL).
{ const rows = DATA["Step 12: Read offers with no pick"].map(i => i.json); const cutoff = Date.now() - Number(DATA['Config'][0].json.pick_hours) * 3600000;
  DATA["Step 12: Read offers with no pick"] = rows.filter(o => o.decision === 'slots offered' && new Date(o.decided_at).getTime() <= cutoff
    && !rows.some(p => p.item === o.item && p.id > o.id)).map(o => ({ json: { id: o.id, item: o.item } }));
  // None waiting: one empty row, as n8n's Postgres node gives (alwaysOutputData); the rule drops it.
  if (!DATA["Step 12: Read offers with no pick"].length) DATA["Step 12: Read offers with no pick"] = [{ json: {} }]; }
const BODIES = (out) => ({"reserve_body": JSON.stringify({ p_recipe: 'R10.2', p_key: 'no pick:' + out.offer }), "task_body": JSON.stringify({ id: 'NP-' + out.offer, to: $('Config').first().json.dispatch_queue, job: out.job, type: 'no pick', reason: 'No pick in 24 hours: decide whether to phone.' })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 12: offers with no reply in 24 hours.
return $input.all().filter(i => i.json.id).map(i => ({ json: { offer: String(i.json.id), job: i.json.item } }));
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };
